        'schemaVersion': schemaVersion,
        'kind': kind,
        'id': id,
        'key': key,
        if (description != null) 'description': description!,
        'type': type,
        if (schema != null) 'schema': schema!.value,
        'default': defaultValue,
        if (segments != null) 'segments': [for (final e in segments!) e.toJson()],
      };
}

