      pure: m['pure'] == null ? null : m['pure']! as bool,
      cacheTtlSeconds: m['cacheTtlSeconds'] == null ? null : (m['cacheTtlSeconds']! as num).toInt(),
      tests: m['tests'] == null ? null : [for (final e in m['tests']! as List<Object?>) FunctionTestCase.fromJson(e!)],
